//! The MySQL/MariaDB repository of tags against a real database
//! migrated with the application's migrations: round trip, optimistic
//! locking and cursor pages. Generated by
//! `forge generate scaffold`.
//!
//! MySQL and MariaDB tests need `FORGE_TEST_MYSQL_URL` or
//! `FORGE_TEST_MARIADB_URL` (a user that may create databases) and are
//! ignored by default: `cargo test -- --include-ignored`.

use std::error::Error;

use app::application::ports::tag_repository::{TagRepository, TagStoreError};
use app::domain::entities::tag::{Tag, TagAttributes};
use app::infrastructure::database::tags::MySqlTagRepository;
use forge::core::Version;
use forge::db::MySqlDatabase;
use forge::db::testing::TestDatabase;

type TestResult = Result<(), Box<dyn Error>>;

static MIGRATOR: sqlx::migrate::Migrator = sqlx::migrate!();

fn attributes() -> Result<TagAttributes, Box<dyn Error>> {
    Ok(TagAttributes {
        label: "Example label".to_owned(),
        active: Some(true),
    })
}

async fn exercise(database: &MySqlDatabase) -> TestResult {
    let repository = MySqlTagRepository::new(database.clone());
    let tag = Tag::new(attributes()?)?;

    repository.insert(&tag).await?;
    assert_eq!(repository.find(tag.id()).await?, Some(tag.clone()));

    let version = repository.update(&tag).await?;
    assert_eq!(version.get(), 2);
    assert!(matches!(
        repository.update(&tag).await,
        Err(TagStoreError::Conflict)
    ));
    assert!(matches!(
        repository.delete(tag.id(), Version::INITIAL).await,
        Err(TagStoreError::Conflict)
    ));
    let stored = repository.find(tag.id()).await?;
    assert_eq!(stored.map(|stored| stored.version()), Some(version));

    for _ in 0..2 {
        repository.insert(&Tag::new(attributes()?)?).await?;
    }
    let first = repository.page(None, 2).await?;
    assert_eq!(first.tags.len(), 2);
    assert_eq!(first.tags[0].id(), tag.id());
    assert!(first.next.is_some());
    let rest = repository.page(first.next, 2).await?;
    assert_eq!(rest.tags.len(), 1);
    assert!(rest.next.is_none());

    repository.delete(tag.id(), version).await?;
    assert_eq!(repository.find(tag.id()).await?, None);
    Ok(())
}

#[tokio::test]
#[ignore = "needs FORGE_TEST_MYSQL_URL"]
async fn mysql_round_trip_locking_and_pages() -> TestResult {
    let database = TestDatabase::<sqlx::MySql>::create(&MIGRATOR).await?;
    exercise(database.database()).await?;
    database.cleanup().await?;
    Ok(())
}

#[tokio::test]
#[ignore = "needs FORGE_TEST_MARIADB_URL"]
async fn mariadb_round_trip_locking_and_pages() -> TestResult {
    let url = forge::db::testing::MARIADB_URL_ENV;
    let database = TestDatabase::<sqlx::MySql>::create_from_env(url, &MIGRATOR).await?;
    exercise(database.database()).await?;
    database.cleanup().await?;
    Ok(())
}
